import { cacheLife, cacheTag } from 'next/cache'

export type Post = {
  id: string
  title: string
  content: string
}

// Stand-in for a real database. Module scope keeps it alive for the lifetime of
// the server process, which is enough to demonstrate the caching behavior.
const posts: Post[] = [
  {
    id: '1',
    title: 'Hello world',
    content: 'The first post.',
  },
]

export const POSTS_TAG = 'posts'

export async function getPosts(): Promise<Post[]> {
  'use cache'
  // Tagging the cache entry is what lets `updateTag('posts')` invalidate it.
  cacheTag(POSTS_TAG)
  // Cache until explicitly invalidated — the action below is the only writer.
  cacheLife('max')

  return posts.map((post) => ({ ...post }))
}

export async function insertPost(data: Omit<Post, 'id'>): Promise<Post> {
  const post: Post = { id: String(posts.length + 1), ...data }
  posts.push(post)
  return { ...post }
}

