'use server'

import { updateTag } from 'next/cache'

import { insertPost, POSTS_TAG } from './lib/posts'

export async function createPost(formData: FormData) {
  const title = formData.get('title')
  const content = formData.get('content')

  if (typeof title !== 'string' || title.trim() === '') {
    throw new Error('Title is required')
  }
  if (typeof content !== 'string' || content.trim() === '') {
    throw new Error('Content is required')
  }

  await insertPost({ title: title.trim(), content: content.trim() })

  // `updateTag` — not `revalidateTag` — because this must guarantee no stale
  // content is served: it expires the 'posts' entry immediately, so the next
  // read blocks on fresh data instead of getting stale-while-revalidate.
  // Only valid inside a Server Action, which is what this is.
  updateTag(POSTS_TAG)
}

